-- Weekly email digest, milestone 1. Additive only: two new tables, no change to existing tables.
-- HIGH risk (schema). Needs a named human owner on the PR. Rollback = the migrate:down section.
--
-- Written in portable SQL (TEXT / INTEGER / CHECK). Timestamps are UTC ISO-8601 text, ids are
-- uuid strings generated by the application. If the primary DB is Postgres, the owner may prefer
-- native uuid/timestamptz/boolean types: change them here before merge; app/digest/models.py maps
-- values by column order and does not depend on the type names.
--
-- user_id and dashboard_id have no foreign keys because the existing user/dashboard tables are not
-- visible from this repo. The owner should add them if those tables are known (additive, same file).

-- migrate:up
CREATE TABLE digest_subscription (
    id                   TEXT PRIMARY KEY,
    user_id              TEXT NOT NULL,
    dashboard_id         TEXT NOT NULL,
    enabled              INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)),
    weekday              INTEGER NOT NULL CHECK (weekday BETWEEN 0 AND 6),
    hour_local           INTEGER NOT NULL CHECK (hour_local BETWEEN 0 AND 23),
    tz                   TEXT NOT NULL,
    next_send_at         TEXT NOT NULL,
    last_sent_at         TEXT,
    consecutive_failures INTEGER NOT NULL DEFAULT 0 CHECK (consecutive_failures >= 0),
    unsubscribed_at      TEXT,
    created_at           TEXT NOT NULL,
    updated_at           TEXT NOT NULL,
    CONSTRAINT digest_subscription_user_dashboard_uniq UNIQUE (user_id, dashboard_id)
);

-- The scheduler tick selects: enabled = 1 AND next_send_at <= now.
CREATE INDEX digest_subscription_due_idx ON digest_subscription (enabled, next_send_at);

CREATE TABLE digest_send (
    id                  TEXT PRIMARY KEY,
    subscription_id     TEXT NOT NULL REFERENCES digest_subscription (id) ON DELETE CASCADE,
    period_start        TEXT NOT NULL,
    status              TEXT NOT NULL
                        CHECK (status IN ('sent', 'skipped_empty', 'skipped_no_access', 'failed')),
    provider_message_id TEXT,
    error_code          TEXT,
    summary_hash        TEXT,
    created_at          TEXT NOT NULL,
    -- The double-send guard: one outcome per subscription per period.
    CONSTRAINT digest_send_subscription_period_uniq UNIQUE (subscription_id, period_start)
);

-- migrate:down
DROP TABLE digest_send;
DROP INDEX digest_subscription_due_idx;
DROP TABLE digest_subscription;
